import React from 'react';
import ReactDOM from 'react-dom';
import { Menu } from '@alifd/next';

const { Item, Group, SubMenu } = Menu;

function App() {
  return (
    <div style={{ width: 240 }}>
      {/* Reproduce: notice the explicit {' '} before the Item below */}
      <Menu defaultOpenKeys="sub-menu">
        <Group label="Group Label 1">
          {' '}
          <Item key="1">Navigation One</Item>
        </Group>
      </Menu>

      {/* Similarly for SubMenu: any whitespace/newline before children will crash */}
      <Menu defaultOpenKeys="sub-menu" style={{ marginTop: 20 }}>
        <SubMenu key="sub-menu" label="Sub Menu">
          {' '}
          <Item key="sub-1">Sub Navigation 1</Item>
        </SubMenu>
      </Menu>
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('mountNode'));
